    e.preventDefault();
    if (!canSubmit) return;
    setSubmitting(true);
    try {
      const data = await findLoginId(nickname, toPhoneDigits(phone));
      setResult({ status: "found", data });
    } catch (err) {
      setResult({ status: "failed", message: getErrorMessage(err) });
    } finally {
      setSubmitting(false);
    }
